 @BeforeEach void setup()throws Exception{install("agent",false);}
 CatalogSourceFinalProofService.Committed read(){return results.readonly(()->service.readCommitted(ref));}
 void complete(){results.complete();}
 @Test void fourCategoriesUseActualNativeCollectionAndCompleteOriginalResultWithoutNewWrites()throws Exception{
  for(String category:List.of("agent","skill","workflow","model")){install(category,false);assertNull(read());complete();int rows=f.count("1=1");var finalProof=read();assertNotNull(finalProof);assertEquals(category,CanonicalJson.parse(finalProof.result().json()).path("category").asText());assertEquals(2,CanonicalJson.parse(finalProof.result().json()).path("stage_result").path("decisions").size());assertEquals(1,CanonicalJson.parse(finalProof.result().json()).path("applied_member_count").asInt());assertEquals(prepared.collection,FrozenCollectionManifest.read(CanonicalJson.parse(finalProof.result().json()).get(FrozenCollectionManifest.FIELD)).getFirst());assertEquals(f.clock.instant(),finalProof.minimumObservationTime());assertEquals(finalProof.result().json(),read().result().json());assertEquals(rows,f.count("1=1"));assertEquals(1,f.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));assertEquals(0,f.count("target_type IN ('catalog_source_final_result','source_stage_availability')"));}
 }
 @Test void actualZeroCollectionStillNeedsItsOriginalNativeOriginAndNoSyntheticRoot()throws Exception{
  for(String category:List.of("agent","skill","workflow","model")){install(category,true);int rows=f.count("1=1");var finalProof=read();assertNotNull(finalProof);assertEquals("complete",finalProof.result().coverageState());assertTrue(finalProof.result().summary().contains("没有本次待去重输入"));assertEquals(0,f.count("record_kind IN ('logical_task','ai_attempt')"));assertEquals(rows,f.count("1=1"));f.jdbc.update("DELETE FROM jobs WHERE id=?",prepared.collection.dispositionId());assertThrows(RuntimeException.class,this::read);}
 }
