  String original=f.jdbc.queryForObject("SELECT action_payload FROM jobs WHERE id=?",String.class,id);var body=(tools.jackson.databind.node.ObjectNode)CanonicalJson.parse(original);((tools.jackson.databind.node.ObjectNode)body.get("facts")).put("manifestHash","b".repeat(64));String raw=JdbcFrozenInputs.canonical(body);f.jdbc.update("UPDATE jobs SET action_payload=?,action_payload_hash=? WHERE id=?",raw,JdbcGenerationLineage.hash(raw),id);assertThrows(RuntimeException.class,this::read);f.jdbc.update("UPDATE jobs SET action_payload=?,action_payload_hash=? WHERE id=?",original,hash,id);assertNotNull(read());
